using System;
using Kamilunavo.RepairEmpire.Core;
namespace Kamilunavo.RepairEmpire.Validation {
 public static class RepairInteractionChecks {
  public static int Run(){int n=0;Action<bool,string> check=(ok,name)=>{n++;if(!ok)throw new Exception("REPAIR_INTERACTION_FAIL "+name);};var session=new RepairInteraction(0);
  session.SetHeld(true);check(!session.Tick(.5f,false),"single long frame cannot instantly finish");for(int i=0;i<4;i++)check(!session.Tick(.1f,false),"first hold requires time");check(!session.Tick(.1f,true)&&session.Progress==0,"pause cancels partial hold");session.SetHeld(true);bool finished=false;for(int i=0;i<12;i++)finished|=session.Tick(.1f,false);check(finished,"continuous actual hold completes first stage");check(!session.Tick(.1f,false),"completion cannot repeat");session.SetPhase(1);check(!session.Tap(2)&&session.Taps==0,"wrong order does not advance");check(!session.Tap(0)&&!session.Tap(1)&&!session.Tap(2),"ordered first three fasteners");check(!session.Tap(0)&&session.Taps==0,"wrong later tap resets sequence");for(int i=0;i<3;i++)session.Tap(i);check(session.Tap(3),"four ordered taps finish stage");check(!session.Tap(3),"tap completion cannot repeat");session.SetPhase(2);session.SetHeld(true);for(int i=0;i<4;i++)session.Tick(.1f,false);session.SetHeld(false);check(session.Progress==0,"release resets verification hold");session.SetHeld(true);finished=false;for(int i=0;i<12;i++)finished|=session.Tick(.1f,false);check(finished,"final verification hold completes");session.SetPhase(3);session.SetHeld(true);check(!session.Tick(2,false)&&!session.Tap(0),"finished repair cannot mint stages");var resumed=new RepairInteraction(1);check(resumed.Taps==0&&!resumed.Tick(1,false),"resume restores saved stage without interaction credit");var standard=new RepairInteraction(0,1);var upgraded=new RepairInteraction(0,1.48f);standard.SetHeld(true);upgraded.SetHeld(true);bool faster=false;for(int i=0;i<7;i++){standard.Tick(.1f,false);faster|=upgraded.Tick(.1f,false);}check(faster&&standard.Progress<1,"upgraded workshop finishes a genuine hold sooner");var capped=new RepairInteraction(0,1.48f);capped.SetHeld(true);check(!capped.Tick(5,false)&&capped.Progress<.2f,"upgraded repair still caps a long frame");check(Math.Abs(RepairRules.VehicleSpeed(0)-22)<.001&&RepairRules.VehicleSpeed(1)>RepairRules.VehicleSpeed(0)&&RepairRules.VehicleSpeed(2)>RepairRules.VehicleSpeed(1),"vehicle progression changes actual speed limits");check(RepairRules.WorkshopRate(new RepairProfile{Workshop=5})==1.48f,"bounded workshop progress gives specified efficiency");Console.WriteLine("REPAIR_INTERACTION_PASS "+n);return n;}
#if REPAIR_INTERACTION_EXE
  public static void Main(){Run();}
#endif
 }
}
